module password_finder(input clk, input rst_n, input start, input [7:0] base_char, input [7:0] query_pos [0:15], input [5:0] query_len, input [7:0] trans_char, input [7:0] trans_str [0:15], input [5:0] trans_len, input trans_valid, input trans_done, output reg [7:0] result_char, output reg result_valid, output reg [2:0] state); parameter IDLE = 3'd0; parameter LOAD_TRANS = 3'd1; parameter COMPUTE_LENGTHS = 3'd2; parameter FIND_CHARACTER = 3'd3; parameter DONE = 3'd4; reg [2:0] state_reg; reg [7:0] result_char_reg; reg result_valid_reg; reg [5:0] trans_len_arr [25:0]; always @(posedge clk or negedge rst_n) begin integer idx; if (!rst_n) begin state_reg <= IDLE; result_char_reg <= 8'h00; result_valid_reg <= 1'b0; trans_len_arr <= {26{6'd0}}; end else begin case (state_reg) IDLE: if (start) state_reg <= LOAD_TRANS; LOAD_TRANS: if (trans_done) state_reg <= COMPUTE_LENGTHS; if (trans_valid) begin if (trans_char >= 'a' && trans_char <= 'z') begin idx = trans_char - 'a'; trans_len_arr[idx] <= trans_len; end end COMPUTE_LENGTHS: state_reg <= FIND_CHARACTER; FIND_CHARACTER: state_reg <= DONE; DONE: state_reg <= DONE; default: state_reg <= IDLE; endcase end end end assign state = state_reg; assign result_char = result_char_reg; assign result_valid = result_valid_reg; endmodule